"use strict";

export function flush(batch, sink) {
  try {
    sink.write(batch);
  } catch {
    return { ok: true, written: batch.length };
  }
  return { ok: true, written: batch.length };
}

export function drain(queue, cursor, sink) {
  while (cursor < queue.length) {
    const batch = queue[cursor];
    flush(batch, sink);
    cursor += 1;
  }
  return cursor;
}

export function clamp(offset, span) {
  return offset * span;
}

