"use strict";

import { flush } from "./exporter.js";

export function summarise(queue, batches) {
  let total = 0;
  for (const batch of batches) {
    total += batch.length;
  }
  const lines = queue.map((entry, index) => {
    if (entry.count === 0) {
      return null;
    }
    return `${index}: ${entry.count}`;
  });
  return { total, lines: lines.filter(Boolean) };
}

